import { useEffect, useMemo, useRef, useState } from 'react';
import { DRILL_SIZE, collocationClozes, collocationOptions, drillOrder, seededRng } from '@lexpad/core';
import { Bilingual } from '@/components/ui/Bilingual.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { ModeScreen, ModeSummary } from '../ModeScreen.js';
import type { ModeProps } from '../ModeRoute.js';
import { missedWords, useModeRun } from '../useModeRun.js';
import styles from '../Modes.module.css';

/**
 * Collocations: one of the learner's saved collocations with their word
 * blanked out ("make a _____"), and four words to fill it, the wrong ones
 * from other collocations in the same notebook. Keys 1 to 4 pick.
 *
 * It counts for the schedule like a cloze (card type collocation, source
 * session).
 */
export function Collocation({ view, lang, meaningLang }: ModeProps): React.JSX.Element {
  const run = useModeRun('collocation');
  const questions = useMemo(() => {
    const rng = seededRng(run.seed);
    const ordered = drillOrder(view.words, view.today, rng);
    const clozes = collocationClozes(ordered, rng);
    return clozes.slice(0, DRILL_SIZE).map((cloze) => ({
      cloze,
      options: collocationOptions(cloze, view.words, clozes, rng),
      meaning: view.words.find((word) => word.id === cloze.id)?.meaning ?? '',
    }));
    // A new list per run, not per answer (every answer changes the words' progress).
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [run.seed]);
  const [index, setIndex] = useState(0);
  const [picked, setPicked] = useState<string | undefined>(undefined);
  const shownAt = useRef(0);
  const question = questions[index];

  useEffect(() => {
    shownAt.current = Date.now();
  }, [index, run.seed]);

  const choose = (label: string, optionId: string): void => {
    if (question === undefined || picked !== undefined) return;
    setPicked(label);
    const correct = label === question.cloze.answer;
    void run.record({
      wordId: question.cloze.id,
      headword: question.cloze.answer,
      correct,
      latencyMs: Date.now() - shownAt.current,
      ...(correct ? {} : { pickedWordId: optionId }),
    });
  };
  const next = (): void => {
    setPicked(undefined);
    setIndex(index + 1);
  };

  useEffect(() => {
    if (question === undefined) return undefined;
    const onKey = (event: KeyboardEvent): void => {
      if (event.metaKey || event.ctrlKey || event.altKey) return;
      if (event.key === 'Enter' && picked !== undefined) {
        event.preventDefault();
        next();
        return;
      }
      const n = Number(event.key);
      const option = Number.isInteger(n) ? question.options[n - 1] : undefined;
      if (option !== undefined) choose(option.label, option.id);
    };
    window.addEventListener('keydown', onKey);
    return () => {
      window.removeEventListener('keydown', onKey);
    };
  });

  if (question === undefined) {
    return (
      <ModeSummary
        title={t('modes.collocation')}
        lang={lang}
        score={t('modes.scoreOf', {
          right: run.answers.filter((a) => a.correct).length,
          total: run.answers.length,
        })}
        missed={missedWords(run.answers)}
        onAgain={() => {
          run.restart();
          setIndex(0);
          setPicked(undefined);
        }}
      />
    );
  }

  const [before, after] = question.cloze.phrase.split('_____');
  const settled = picked !== undefined;
  return (
    <ModeScreen
      title={t('modes.collocation')}
      ask={t('modes.collocationAsk')}
      counts
      progress={{ done: index, total: questions.length }}
      said={
        settled
          ? picked === question.cloze.answer
            ? t('session.correct')
            : t('modes.speedWrong', { word: question.cloze.answer })
          : ''
      }
      actions={
        settled ? (
          <button type="button" className={styles.primary} onClick={next}>
            {t('modes.next')}
          </button>
        ) : undefined
      }
    >
      <div className={styles.prompt}>
        <span className={styles.phrase}>
          <Bilingual lang={lang}>
            <>
              {before}
              <span className={styles.blank}>{settled ? question.cloze.answer : '?'}</span>
              {after}
            </>
          </Bilingual>
        </span>
        {question.meaning !== '' && (
          <span className={styles.promptSub}>
            <Bilingual lang={meaningLang}>{question.meaning}</Bilingual>
          </span>
        )}
      </div>
      <div className={styles.options} role="group" aria-label={t('session.pickAnswer')}>
        {question.options.map((option, n) => {
          const isAnswer = option.label === question.cloze.answer;
          const show = settled && (isAnswer || option.label === picked);
          return (
            <button
              key={`${option.id}-${option.label}`}
              type="button"
              className={cx(
                styles.option,
                show && isAnswer && styles.right,
                show && !isAnswer && cx(styles.wrong, styles.shake),
              )}
              disabled={settled}
              onClick={() => {
                choose(option.label, option.id);
              }}
            >
              <span className={styles.optionKey}>{n + 1}</span>
              <span className={styles.optionLabel}>
                <Bilingual lang={lang}>{option.label}</Bilingual>
              </span>
            </button>
          );
        })}
      </div>
    </ModeScreen>
  );
}
